using System;using System.IO;using System.Linq;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.UI;using ElDespacho;
public class GameplayCoverageProbe:MonoBehaviour {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;DespachoGame g;DeskMenus m;AccessController a;string dir;List<string> log=new List<string>();DespachoGame.SaveData baseline;bool Updated=>DeskMenus.Version=="v0.9.13-prototipo";
 void Check(bool b,string s){log.Add((b?"PASS ":"FAIL ")+s);File.WriteAllLines(dir+"/results.txt",log);if(!b)throw new Exception(s);}
 void Call(string n,params object[] args)=>typeof(DespachoGame).GetMethod(n,F).Invoke(g,args);
 object Get(string n)=>typeof(DespachoGame).GetField(n,F).GetValue(g);
 void Set(string n,object v)=>typeof(DespachoGame).GetField(n,F).SetValue(g,v);
 IEnumerator Tick(){a.Refresh();yield return null;yield return null;yield return new WaitForSecondsRealtime(.2f);Canvas.ForceUpdateCanvases();}
 IEnumerator Shot(string n){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(dir+"/"+n+".png",t.EncodeToPNG());Destroy(t);}
 string State(){var s=g.CaptureSave();s.utcTicks=1;return JsonUtility.ToJson(s);}
 string[] screens={"despacho","documento","resultado","mapa","dialogo","dossier","inteligencia","tutorial","pausa","guardados"};
 IEnumerator Scene(string name){a.ClosePanels();m.Resume();DeskPreferences.Current.tutorial=false;Call("RestoreSave",JsonUtility.FromJson<DespachoGame.SaveData>(JsonUtility.ToJson(baseline)));Call("ShowOffice");
 if(name=="documento"||name=="resultado"){Set("documentOpened",true);Call("ShowOffice");if(name=="resultado")Call("AnswerCard",true);}
 if(name=="mapa")Call("ShowMap");
 if(name=="dialogo"||name=="dossier"||name=="inteligencia"){var c=((List<Country>)Get("countries")).First();Call("StartVisit",c);if(name=="dialogo")Call("Ask",c.questions.First());if(name=="inteligencia"){Set("docTab",1);Call("ShowVisit");}}
 if(name=="tutorial")DeskPreferences.Current.tutorial=true;if(name=="pausa")m.ShowPause();if(name=="guardados")m.ShowSlots(true);yield return Tick();}
 IEnumerator Start(){dir="Logs/GameplayCoverage-"+DeskMenus.Version;Directory.CreateDirectory(dir);Application.logMessageReceived+=(s,st,t)=>{if(t==LogType.Error||t==LogType.Exception){File.AppendAllText(dir+"/results.txt",s+st);EditorApplication.Exit(1);}};yield return null;yield return null;a=AccessController.Instance;g=a.GetComponent<DespachoGame>();m=a.GetComponent<DeskMenus>();DeskPreferences.Current.tutorial=false;DeskPreferences.Current.autosave=false;m.Resume();g.StartFromMenu();Call("ShowOffice");yield return Tick();baseline=g.CaptureSave();a.Speech.Probe();yield return new WaitForSecondsRealtime(3);
 for(int profile=0;profile<4;profile++){
 AccessPreferences.Reset();AccessPreferences.Current.narrationVolume=0; // Tests execute speech without broadcasting it to the room.
 foreach(string screen in screens){yield return Scene(screen);yield return Shot(profile+"-"+screen+"-off");string state=State();var before=a.Snapshot().Select(x=>x.text).ToArray();AccessPreferences.Current.ToggleProfile(profile,a.Speech.Ready);yield return Tick();yield return Shot(profile+"-"+screen+"-on");Check(!a.IsReadingView,"profile "+profile+" "+screen+" stays illustrated");Check(State()==state,"profile "+profile+" "+screen+" preserves campaign");
 if(Updated&&profile==0){var adapted=g.GetComponentsInChildren<MonoBehaviour>().Where(x=>x.GetType().Name=="GameplayTextAccess").ToArray();Check(adapted.Length>0,"reading adapted text exists "+screen);var displayed=g.GetComponentsInChildren<Text>().Where(t=>t.GetComponent("GameplayTextVisual")!=null).ToArray();Check(displayed.Length>0&&displayed.All(t=>t.color==Color.white&&!t.resizeTextForBestFit),"reading actual white, enlarged unshrunk text "+screen);Check(displayed.All(t=>t.preferredHeight<=t.rectTransform.rect.height+3),"reading full text fits scroll content "+screen);}
 if(Updated&&profile==2&&(screen=="mapa"||screen=="dialogo"||screen=="inteligencia"))Check(a.Snapshot().Any(e=>e.text.Contains("HERRAMIENTAS")),"guided contextual tools "+screen);
 if(Updated&&profile==3){Check(a.Speech.Ready&&a.Speech.Error=="","speech worker ready "+screen);var method=typeof(AccessController).GetMethod("NarrationSnapshot");string actual=(string)method.Invoke(a,null);Check(actual.Contains("Opciones disponibles")&&actual.Length>50,"narration includes live content and choices "+screen);Check(a.Speech.Last.Contains("Opciones disponibles"),"automatic live narration includes choices "+screen);int accepted=a.Speech.Accepted;a.Speech.Say(actual,true);yield return Tick();Check(a.Speech.Accepted>accepted,"speech worker accepted current request "+screen);Check(a.Speech.Last==actual,"speech latest content "+screen);File.WriteAllText(dir+"/speech-"+screen+".txt",actual);}
 AccessPreferences.Current.ToggleProfile(profile,a.Speech.Ready);yield return Tick();Check(AccessPreferences.Current.profileMask==0&&AccessPreferences.Current.textScale==1&&!DeskPreferences.Current.highContrast,"profile reversible "+profile+" "+screen);
 }
 AccessPreferences.Current.ToggleProfile(profile,a.Speech.Ready);AccessPreferences.Current.Save();DeskPreferences.Current.Save();string saved=JsonUtility.ToJson(AccessPreferences.Current);AccessPreferences.Load();Check(JsonUtility.ToJson(AccessPreferences.Current)==saved,"profile reload "+profile);AccessPreferences.Current.ToggleProfile(profile,a.Speech.Ready);
 }
 if(Updated){foreach(int mask in new[]{5,3,12,15}){AccessPreferences.Reset();AccessPreferences.Current.narrationVolume=0;for(int p=0;p<4;p++)if((mask&(1<<p))!=0)AccessPreferences.Current.ToggleProfile(p,a.Speech.Ready);foreach(string s in new[]{"documento","dialogo","inteligencia"}){yield return Scene(s);Check(!a.IsReadingView&&g.GetComponentsInChildren<Button>().Any(b=>b.IsInteractable()),"combination "+mask+" usable "+s);yield return Shot("combined-"+mask+"-"+s);}}
 var asm=typeof(Editor).Assembly;var flags=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;var st=asm.GetType("UnityEditor.GameViewSizes");var sizes=st.GetProperty("instance",BindingFlags.Public|BindingFlags.Static|BindingFlags.FlattenHierarchy).GetValue(null);var group=st.GetMethod("GetGroup").Invoke(sizes,new[]{Enum.Parse(asm.GetType("UnityEditor.GameViewSizeGroupType"),"Standalone")});var gt=group.GetType();int index=(int)gt.GetMethod("GetTotalCount").Invoke(group,null);var size=Activator.CreateInstance(asm.GetType("UnityEditor.GameViewSize"),flags,null,new object[]{Enum.Parse(asm.GetType("UnityEditor.GameViewSizeType"),"FixedResolution"),1280,720,"Gameplay audit temporary"},null);gt.GetMethod("AddCustomSize").Invoke(group,new[]{size});var window=EditorWindow.GetWindow(asm.GetType("UnityEditor.GameView"));var selected=window.GetType().GetProperty("selectedSizeIndex",flags);int old=(int)selected.GetValue(window);
 try{selected.SetValue(window,index);yield return new WaitForSecondsRealtime(.5f);Check(Screen.width==1280&&Screen.height==720,"actual 1280x720");foreach(float scale in new[]{.75f,1f,1.25f,1.5f,1.75f})foreach(string s in screens){AccessPreferences.Current.textScale=scale;yield return Scene(s);Check(!a.IsReadingView,"visual scale "+scale+" "+s);var texts=g.GetComponentsInChildren<Text>().Where(t=>t.GetComponent("GameplayTextVisual")!=null);Check(texts.All(t=>t.preferredHeight<=t.rectTransform.rect.height+3),"scroll text fits "+scale+" "+s);if(scale==1.75f&&s=="dialogo"){var dialog=g.GetComponentsInChildren<RectTransform>().First(r=>r.name=="Dialog");Check(dialog.anchorMin.y>.2f,"diplomatic layout actually reserves enlarged controls");Check(g.GetComponentsInChildren<RectTransform>().Any(r=>r.name=="QuestionsViewport"),"questions reflow exists");}if(scale==1.75f)yield return Shot("720p-175-"+s);}}finally{selected.SetValue(window,old);gt.GetMethod("RemoveCustomSize").Invoke(group,new object[]{index});}
 }
 AccessPreferences.Current.Save();DeskPreferences.Current.Save();File.WriteAllText("Logs/GameplayCoverage-dir.txt",DeskPreferences.TestDirectory);File.WriteAllText("Logs/GameplayCoverage-expected.txt",JsonUtility.ToJson(AccessPreferences.Current));log.Add("COMPLETE "+log.Count(x=>x.StartsWith("PASS "))+" PASS; automated Play Mode, no physical input/hearing evaluation");File.WriteAllLines(dir+"/results.txt",log);EditorApplication.Exit(0);
 }
}
public static class GameplayCoverageRunner {
 public static void Run(){SessionState.SetBool("GameplayCoverage",true);SessionState.SetString("GameplayCoverageDir",Path.Combine(Path.GetTempPath(),"DespachoCoverage-"+Guid.NewGuid().ToString("N")));EditorApplication.EnterPlaymode();}
 public static void Restart(){DeskPreferences.TestDirectory=File.ReadAllText("Logs/GameplayCoverage-dir.txt");DeskPreferences.Load();AccessPreferences.Load();bool ok=JsonUtility.ToJson(AccessPreferences.Current)==File.ReadAllText("Logs/GameplayCoverage-expected.txt");File.WriteAllText("Logs/GameplayCoverage-restart.txt",ok?"PASS separate process restored combined profiles/custom settings":"FAIL restart");EditorApplication.Exit(ok?0:1);}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Before(){if(SessionState.GetBool("GameplayCoverage",false))DeskPreferences.TestDirectory=DeskSaveStore.TestDirectory=SessionState.GetString("GameplayCoverageDir","");}
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void After(){if(!SessionState.GetBool("GameplayCoverage",false))return;SessionState.SetBool("GameplayCoverage",false);new GameObject("GameplayCoverage").AddComponent<GameplayCoverageProbe>();}
}
